(function(){"use strict";var M=window.MNEMIKA;if(!M)return;
 var P=window.MNEMIKA_SUBJECT_PICT;
 /* Das Bild eines Kapitels kommt aus dem Fach des Kapitels, nicht aus der Reihenfolge
    der eingebetteten Daten. Form und Beschriftung bleiben wie zuvor. */
 var base=M.mediaFor;
 M.mediaFor=function(id){
   var m=base?base.call(M,id):null;
   var c=M.chapter&&M.chapter(id);
   if(!c) return m;
   var src=P[c.subject]||P.orientation;
   var label=(M.SUBJECTS&&M.SUBJECTS[c.subject]&&M.SUBJECTS[c.subject].label)||c.subject;
   if(!m) return {id:"pict-"+c.subject,src:src,data:src,alt:label,caption:"",
     credit:"Stoffknacker",licence:"eigene Grafik",provenance:"own",kind:"pictogram"};
   var o={}; for(var k in m) o[k]=m[k];
   o.src=src; o.data=src; o.alt=label; o.source="Stoffknacker"; o.rights="eigene Grafik"; o.caption=""; o.credit="Stoffknacker";
   o.licence="eigene Grafik"; o.provenance="own"; o.kind="pictogram";
   return o;};

 /* Auch die Datenquelle selbst umstellen, nicht nur den Zugriff:
    Kapitellisten lesen MEDIA_BY_CHAPTER direkt. */
 if (M.MEDIA_BY_CHAPTER && M.chapters) {
   M.chapters.forEach(function (c) {
     var src = P[c.subject] || P.orientation;
     var label = (M.SUBJECTS && M.SUBJECTS[c.subject] && M.SUBJECTS[c.subject].label) || c.subject;
     var entry = { credit:"Stoffknacker", licence:"eigene Grafik", provenance:"own", rights:"eigene Grafik", source:"Stoffknacker", id: "pict-" + c.subject, src: src, data: src, alt: label, caption: "",
       credit: "Stoffknacker", licence: "eigene Grafik", provenance: "own", kind: "pictogram" };
     var cur = M.MEDIA_BY_CHAPTER[c.id];
     if (Array.isArray(cur) && cur.length) {
       var keep = {}; for (var k in cur[0]) keep[k] = cur[0][k];
       for (var k2 in entry) keep[k2] = entry[k2];
       M.MEDIA_BY_CHAPTER[c.id] = [keep].concat(cur.slice(1));
     } else {
       M.MEDIA_BY_CHAPTER[c.id] = [entry];
     }
   });
 }
 M.pictogramAudit=function(){
   var wrong=M.chapters.filter(function(c){
     var m=M.mediaFor(c.id); return !m||m.src!==(P[c.subject]||P.orientation);});
   return {chapters:M.chapters.length,correct:M.chapters.length-wrong.length,
     wrong:wrong.map(function(c){return c.id;})};};
 })();

