(function(){"use strict";var M=window.MNEMIKA;if(!M)return;

/* Erklärung oben in die Abschlusswahl setzen, Kopf um nützliche Anzeigen ergänzen */
function mountWelcome(){
  var v=document.getElementById("v-programs");
  if(!v||v.hidden||v.dataset.pupilFirst==="1") return;
  if(v.querySelector(".wx-hero")) return;
  var host=document.createElement("div");
  host.className="wx-wrap";
  host.innerHTML=M.welcomeHTML();
  v.insertBefore(host,v.firstChild);
  var old=v.querySelector(".wchero"); if(old) old.remove();
}
/* Kopfzeile: Abschluss, Konfiguration, Zieldatum, Fortschritt auf einen Blick */
M.paintHeaderInfo=function(){
  var bar=document.querySelector(".top-in"); if(!bar) return;
  var box=document.getElementById("mn-headinfo");
  if(!box){ box=document.createElement("div"); box.id="mn-headinfo"; box.className="hdinfo";
    var pill=document.getElementById("progpill");
    if(pill&&pill.parentNode) pill.parentNode.insertBefore(box,pill.nextSibling); else bar.appendChild(box); }
  var pid=M.activeProgram&&M.activeProgram(), pl=M.learningPlanV34&&M.learningPlanV34();
  var cfgId=M.configChoice&&M.configChoice(pid);
  var cfgs=(M.configurationsFor&&M.configurationsFor(pid))||[];
  var cfg=cfgs.filter(function(c){return c.id===cfgId;})[0];
  var bits=[];
  if(cfg) bits.push('<span class="hdi" title="Ausrichtung">'+M.esc(cfg.label.slice(0,34))+'</span>');
  if(pl&&pl.targetDate){
    var days=Math.ceil((new Date(pl.targetDate)-new Date())/864e5);
    bits.push('<span class="hdi"><b>'+(days>0?days:0)+'</b> Tage</span>');
  }
  if(pl&&pl.moduleCount) bits.push('<span class="hdi"><b>'+pl.moduleCount+'</b> Module</span>');
  box.innerHTML=bits.join("");
  box.hidden=!bits.length;
};
var go0=M.go;
if(typeof go0==="function"){
  M.go=function(){ var r=go0.apply(this,arguments);
    setTimeout(function(){ mountWelcome(); M.paintHeaderInfo(); },0); return r; };
}
setTimeout(function(){ mountWelcome(); M.paintHeaderInfo(); },300);
setTimeout(function(){ mountWelcome(); M.paintHeaderInfo(); },1200);
})();

