(function(){"use strict";var M=window.MNEMIKA;if(!M)return;

/* ============================================================
   85 Fragetexte kommen mehrfach vor, meist in zwei Kapiteln.
   Nichts wird geloescht: der Inhalt gehoert beiden Kapiteln.
   Stattdessen sieht niemand denselben Wortlaut zweimal in einer
   Sitzung, und in der Kapitelansicht sagt ein Zusatz, woher er kommt.
   ============================================================ */
M.duplicatePrompts=function(){
 var seen={}, dup={};
 M.chapters.forEach(function(c){
  var all=(c.questions||[]).concat((c.blocks||[]).map(function(b){return b&&b.check;}).filter(Boolean));
  all.forEach(function(q){ if(!q||!q.prompt) return;
   var k=q.prompt.trim();
   if(seen[k]) { (dup[k]=dup[k]||[seen[k]]).push({chapter:c.id,id:q.id}); }
   else seen[k]={chapter:c.id,id:q.id};
  });});
 return dup;
};
/* Kennzeichnung auf den Fragen selbst, damit die Auswahl sie erkennt. */
M.markDuplicates=function(){
 var dup=M.duplicatePrompts(), n=0;
 M.chapters.forEach(function(c){
  var all=(c.questions||[]).concat((c.blocks||[]).map(function(b){return b&&b.check;}).filter(Boolean));
  all.forEach(function(q){ if(!q||!q.prompt) return;
   var k=q.prompt.trim();
   if(dup[k]){ q.__dupKey=k; n++; }
  });});
 return {marked:n, distinct:Object.keys(dup).length};
};
/* Eine Auswahl darf jeden Wortlaut nur einmal enthalten. */
M.dedupeSelection=function(list){
 if(!Array.isArray(list)) return list;
 var used={}, out=[];
 list.forEach(function(item){
  var q=item&&item.q?item.q:item;
  var k=(q&&(q.__dupKey||q.prompt))||"";
  if(k && used[k]) return;
  if(k) used[k]=1;
  out.push(item);
 });
 return out;
};
/* In die vorhandene Aufgabenauswahl einhaengen, ohne sie zu ersetzen. */
["pickQuestions","buildRun","blueprint","selectQuestions"].forEach(function(fn){
 if(typeof M[fn]==="function" && !M[fn].__deduped){
  var base=M[fn];
  M[fn]=function(){ return M.dedupeSelection(base.apply(M, arguments)); };
  M[fn].__deduped=true;
 }
});
(function settle(n){
 if(n>80) return;
 if(M.chapters&&M.chapters.length && !M.__dupMarked){ M.__dupMarked=M.markDuplicates(); return; }
 setTimeout(function(){settle(n+1);},120);
})(0);
})();

