(function(){"use strict";var M=window.MNEMIKA;if(!M)return;

/* ============================================================
   Niemand darf in einem Test haengen bleiben.
   Ueberspringen lief im Kreis: nach 41 Klicks in einem Quiz mit fuenf
   Aufgaben war der Lauf immer noch offen und kein Ergebnis erreichbar.
   Jetzt zaehlt jede Runde, und wenn jede Aufgabe einmal gesehen wurde,
   fuehrt der naechste Klick zur Abgabe statt im Kreis.
   ============================================================ */
var seen = {};
function runObj(){ return M.R || M.RUN || null; }

M.__stillgelegtNoStuck = function(){
  var host = document.getElementById("v-train"); if(!host) return;
  var skip = host.querySelector("#skip");
  var R = runObj();
  if(!skip || skip.__guard) return;
  skip.__guard = true;
  var base = skip.onclick;
  skip.onclick = function(ev){
    /* Das Laufobjekt ist von aussen nicht erreichbar. Deshalb zaehlen wir
       ueber den sichtbaren Fragetext und die Anzahl der Navigationsknoepfe. */
    var r = runObj();
    var promptEl = host.querySelector(".qp") || host.querySelector("h2");
    var key = (r && r.qs && r.qs[r.i] && r.qs[r.i].q && r.qs[r.i].q.id)
           || (promptEl ? promptEl.textContent.trim().slice(0,80) : String(Date.now()));
    seen[key] = (seen[key] || 0) + 1;
    var total = (r && r.qs && r.qs.length) || host.querySelectorAll(".qn").length || 0;
    var visited = Object.keys(seen).length;
    var looped = Object.keys(seen).some(function(k){ return seen[k] >= 2; });
    /* Jede Aufgabe gesehen, oder eine zum zweiten Mal: Schluss mit dem Kreis. */
    if(total && (visited >= total || looped)){
      var end = host.querySelector("#submit, [data-act='submit'], .submit")
             || host.querySelector("#quit");
      if(end){ seen = {}; end.click(); return; }
    }
    if(typeof base === "function") return base.call(this, ev);
  };
};
/* Ein sichtbarer Ausgang, falls doch einmal nichts weitergeht. */
M.__stillgelegtEscape = function(){
  var host = document.getElementById("v-train"); if(!host) return;
  if(host.querySelector(".t-entfernt")) return;
  var q = host.querySelector("#quit"); if(!q) return;
  var p = document.createElement("p");
  p.className = "t-entfernt";
  p.innerHTML = 'Kommst du nicht weiter? <button class="t-entfernt-btn"></button>';
  q.parentNode.insertBefore(p, q.nextSibling);
  p.querySelector(".t-entfernt-btn").onclick = function(){ seen = {}; q.click(); };
};
/* Nach jedem Neuzeichnen wieder anhaengen. */
var mo = new MutationObserver(function(){ M.__stillgelegtNoStuck(); M.__stillgelegtEscape(); });
function watch(){
  var host = document.getElementById("v-train");
  if(host){ mo.observe(host, {childList:true, subtree:true}); M.__stillgelegtNoStuck(); M.__stillgelegtEscape(); }
  else setTimeout(watch, 300);
}
if(document.readyState !== "loading") watch();
else document.addEventListener("DOMContentLoaded", watch);
M.resetStuckGuard = function(){ seen = {}; };
})();

